package com.example.payment.architecturetest;

import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.classes;

import com.tngtech.archunit.core.domain.JavaClasses;
import com.tngtech.archunit.core.importer.ClassFileImporter;
import com.tngtech.archunit.core.importer.ImportOption;
import com.tngtech.archunit.lang.ArchRule;
import com.tngtech.archunit.library.Architectures;
import org.junit.jupiter.api.Test;

/**
 * Guards the layering of this module set: domain <- application <- infrastructure <- app.
 *
 * <p>Runs as part of {@code mvn verify} (via maven-failsafe-plugin), not {@code mvn test},
 * so the every-save unit test suite stays fast while the full build still fails when a
 * technical/infrastructure detail (Spring, Jackson, file or HTTP APIs, ...) leaks into
 * business code that should not know about it.
 */
class LayeringArchitectureTest {

    private static final JavaClasses PRODUCTION_CLASSES = new ClassFileImporter()
            .withImportOption(ImportOption.Predefined.DO_NOT_INCLUDE_TESTS)
            .importPackages("com.example.payment");

    @Test
    void domain_does_not_depend_on_anything_else_in_this_codebase() {
        ArchRule rule = classes()
                .that().resideInAPackage("com.example.payment.domain..")
                .should().onlyDependOnClassesThat()
                .resideOutsideOfPackages(
                        "com.example.payment.application..",
                        "com.example.payment.infrastructure..",
                        "com.example.payment.app..");

        rule.check(PRODUCTION_CLASSES);
    }

    @Test
    void application_does_not_depend_on_infrastructure_or_app() {
        ArchRule rule = classes()
                .that().resideInAPackage("com.example.payment.application..")
                .should().onlyDependOnClassesThat()
                .resideOutsideOfPackages(
                        "com.example.payment.infrastructure..",
                        "com.example.payment.app..");

        rule.check(PRODUCTION_CLASSES);
    }

    @Test
    void layers_are_only_accessed_top_down() {
        ArchRule rule = Architectures.layeredArchitecture()
                .consideringOnlyDependenciesInLayers()
                .layer("Domain").definedBy("com.example.payment.domain..")
                .layer("Application").definedBy("com.example.payment.application..")
                .layer("Infrastructure").definedBy("com.example.payment.infrastructure..")
                .layer("App").definedBy("com.example.payment.app..")
                .whereLayer("App").mayNotBeAccessedByAnyLayer()
                .whereLayer("Infrastructure").mayOnlyBeAccessedByLayers("App")
                .whereLayer("Application").mayOnlyBeAccessedByLayers("Infrastructure", "App")
                .whereLayer("Domain").mayOnlyBeAccessedByLayers("Application", "Infrastructure", "App");

        rule.check(PRODUCTION_CLASSES);
    }

    @Test
    void business_code_does_not_leak_technical_frameworks() {
        ArchRule rule = classes()
                .that().resideInAPackage("com.example.payment.domain..")
                .or().resideInAPackage("com.example.payment.application..")
                .should().onlyDependOnClassesThat()
                .resideOutsideOfPackages(
                        "org.springframework..",
                        "com.fasterxml.jackson..",
                        "java.nio.file..",
                        "java.io..");

        rule.check(PRODUCTION_CLASSES);
    }
}

